#!/usr/bin/env python3
"""Render crawlable official archives and the two interactive number labs."""
import datetime as dt, html, json, math, os
from pathlib import Path
ROOT=Path(os.environ.get('LOTTERY_LAB_ROOT',Path(__file__).resolve().parents[2]))
E=html.escape
def write(p,s):
 t=p.with_suffix(p.suffix+'.tmp');t.write_text(s);os.chmod(t,0o644);os.replace(t,p)
def fmt(n):return f'{n:,}'
def day(s):return dt.date.fromisoformat(s).strftime('%d %b %Y').lstrip('0')
def balls(nums,kind=''):return ''.join(f'<span class="ball {kind}">{n}</span>' for n in nums)
def nav(folder):return '<nav class="game-nav" aria-label="Number labs">'+''.join(f'<a href="/{f}/"'+(' aria-current="page"' if f==folder else '')+f'>{n}</a>' for f,n in [('EuroJackpot','EuroJackpot'),('Lotto','Lotto'),('Vikinglotto','Vikinglotto')])+'</nav>'
def head(title,description,folder,page=''):
 url=f'https://setai.no/{folder}/{page}'
 return f'''<!doctype html><html lang="en" data-preview-locked><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | SETAEI</title><meta name="description" content="{E(description)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(description)}"><meta property="og:url" content="{url}"><meta name="theme-color" content="#17171d"><style>html[data-preview-locked] body>*:not(#preview-gate){{display:none!important}}[hidden]{{display:none!important}}</style><script src="/LotteryLab/preview-access.js?v=1"></script><link rel="stylesheet" href="/LotteryLab/style.css?v=1"></head><body class="{'viking' if folder=='Vikinglotto' else 'lotto'}"><header class="topbar"><div class="wrap nav"><a class="logo" href="/">SET<span>AEI</span></a><nav class="navlinks" aria-label="On this page"><a href="/{folder}/#selections">Selections</a><a href="/{folder}/#analysis">Analysis</a><a href="/{folder}/results.html">Results</a></nav><span class="navtag">Number Lab · Preview</span></div></header><main class="wrap">{nav(folder)}'''
def foot():return '</main><footer><div class="wrap footerinner"><span>SETAEI Number Lab · Independent experimental project</span><span>Official results: Norsk Tipping · All times: Europe/Oslo</span></div></footer></body></html>'
def table(rows,c):
 return '<div class="table-scroll"><table class="archive-table"><thead><tr><th>Draw date</th><th>Main numbers</th><th>'+('Viking number' if c['special'] else 'Drawn bonus')+'</th></tr></thead><tbody>'+''.join(f'<tr><td class="result-date">{day(r["date"])}</td><td><div class="balls">{balls(r["main"])}</div></td><td><div class="balls">{balls(r["special"] if c["special"] else r["bonus"],"star")}</div></td></tr>' for r in rows)+'</tbody></table></div>'
def build(folder):
 d=ROOT/folder;h=json.loads((d/'history.json').read_text());a=json.loads((d/'analysis.json').read_text());c=h['config'];rows=h['draws'];latest=rows[-1];name=c['name'];v=bool(c['special']);first_prize=next((x for x in latest['prizes'] if x['id']==1),None);prize_note=('First-prize winners reported by the official feed: '+str(first_prize['winners'])+('. Prize per winner: NOK '+fmt(round(first_prize['amountNOK']))+'.' if first_prize['winners'] else '.')) if first_prize else 'Prize distribution is not available.';total=math.comb(c['n'],c['k'])*(c['special'] or 1);years=sorted(set(r['date'][:4] for r in rows),reverse=True);ev=a['evaluation'];extra_label='Viking number' if v else 'drawn bonus';total_label='All 7 drawn numbers (6 main + Viking)' if v else 'All 8 drawn numbers (7 main + drawn bonus)';rule='Choose 6 different main numbers from 1–48 and 1 Viking number from 1–5. The Viking number is a separate pool and may have the same numeric value as a main number.' if v else 'Choose 7 different numbers from 1–34. One bonus number is then drawn from the remaining 27 numbers. You do not choose an eighth number.';coverage='Current 1–5 Viking-number rules only, from 9 June 2021. Earlier 1–8 rules are excluded.' if v else 'Weekly official draws from 2 January 2016. This is not the complete history since the game began.'
 top=head(f'{name} number lab – results, history and experimental selections',f'{name} official results, number frequencies, date numerology and registered experimental selections. {len(rows)} verified draws through {latest["date"]}.',folder)
 top+=f'''<div class="hero"><div><span class="lab-tag">{name} · Research in public</span><h1>Explore the numbers.<br><em>Measure the guesses.</em></h1><p>Official results, transparent methods and a dated record of every server-generated selection. Explore patterns, then check what actually happens.</p><div class="hero-actions"><a class="button-link primary" href="#selections">Next draw selections ↓</a><a class="button-link" href="#analysis">Explore the archive</a></div></div><div class="orbit" aria-hidden="true"><span class="ring"></span><span class="ring two"></span><span class="dot"></span><div class="core">{c['k']}{'+1' if v else ''}<small>{'MAIN + VIKING' if v else 'MAIN NUMBERS'}</small></div></div></div>
 <div class="meta"><div><strong>{fmt(len(rows))}</strong><small>verified official draws</small></div><div><strong>{'Wednesday' if v else 'Saturday'}</strong><small>entry deadline 18:00 Oslo</small></div><div><strong>{c['k']} / {c['n']}{' + 1 / 5' if v else ''}</strong><small>numbers to select</small></div></div>
 <div class="notice"><strong>Every valid line has the same jackpot chance: 1 in {fmt(total)}.</strong> Patterns, numerology and learned weights do not establish a prediction advantage. Two matches in one draw cannot validate a method.</div>
 <section class="latest-panel card" aria-label="Latest official result"><div><span class="eyebrow">Latest official result</span><h2 id="latest-date">{day(latest['date'])}</h2><p class="tiny">Pink ball: {extra_label}</p></div><div id="latest-balls" class="balls">{balls(latest['main'])}<span class="plus">{'★' if v else '+'}</span>{balls(latest['special'] if v else latest['bonus'],'star')}</div><a href="#archive">View results ↓</a><p class="tiny" id="latest-prize">{prize_note}</p><p class="freshness" id="freshness">Official archive through {day(latest['date'])} · source fetched {E(h['fetchedAt'])}.</p></section>
 <p id="error" role="alert" hidden></p>
 <section id="selections"><div class="bar"><h2>Next draw selections</h2><button type="button" id="reset-ticket">Restore default lines</button></div><p class="game-rule">{rule}</p><div class="draw-tabs" id="draw-tabs" role="tablist" aria-label="Choose draw date"></div><div class="ticket" id="ticket" role="tabpanel"><p class="loading">Loading registered selections…</p></div><p class="ticket-explainer">Filled lines appear first; empty lines stay at the bottom. Changing or removing a line affects this browser view. Original registered forecasts remain in the results record. For a future draw, a registered line stays fixed even if another result arrives first.</p>
 <div class="card personal-panel"><h3>Your personal numerology</h3><p>The same personal year, month, day and life-path calculator as the EuroJackpot lab. Repeated values share a number; documented sums fill the remaining positions. Values are mapped cyclically to the game’s number range.</p><form id="personal-form"><div class="form-grid"><label>Date of birth<input id="birth-date" type="date" required></label><label>Name (optional)<input id="personal-name" type="text" maxlength="200" autocomplete="off"></label><div><button type="submit" class="primary">Complete personal line</button><button type="button" id="personal-clear">Clear</button></div></div></form><p id="personal-error" class="personal-error" role="alert" hidden></p><div class="personal-numbers" id="personal-factors"></div><p class="tiny" id="personal-explanation"></p><p class="privacy-note">Birthday and name stay in browser memory and are cleared when the page reloads. They are not sent to our server. Personal selections are numerology experiments.</p></div></section>
 <section id="methods"><h2>How the lines are calculated</h2><div class="method-grid">
 <article class="card"><span class="badge">Lines 1 &amp; 2</span><h3>Learned AI selections</h3><p>A small regularised logistic model learns how recent frequency, long-run frequency and time since the last appearance relate to earlier results. It converts these signals into number weights and samples a valid line. AI 2 uses the same model with a different fixed random seed.</p><p class="tiny">The date and model version fix the random seed. AI 2 is another sample, not a second independently validated model.</p></article>
 <article class="card"><span class="badge">Calendar</span><h3>Day-of-month hypothesis</h3><p>Reduce the target day of the month to 1–9. Among the latest 400 earlier draws, count numbers from days with that same root. Add the equivalent of 20 draws of smoothed full-history frequencies, then sample without replacement.</p></article>
 <article class="card"><span class="badge">History</span><h3>Previously unseen main set</h3><p>Sample uniformly, rejecting an exact main-number set if it already appears in the available archive. This changes the filter, not the chance of any remaining individual combination.</p></article>
 <article class="card"><span class="badge">Numerology</span><h3>Date and sum-root hypothesis</h3><p>Add all digits of the full target date and reduce to 1–9. For earlier dates with that root, find the most common main-number sum root (lowest root breaks a tie). Sample a uniform line until its main-number sum has that root.</p></article>
 <article class="card"><span class="badge">Control</span><h3>Uniform random line</h3><p>Choose every main set with equal probability{', with a separate uniform Viking number' if v else ''}. This control is recorded alongside the other methods so comparisons include ordinary chance.</p></article>
 <article class="card"><span class="badge">Reproducible</span><h3>Frozen before the draw</h3><p>Each registered line includes its creation timestamp, target date, method version and last known draw date. Results are attached afterwards. Local edits and personal lines are not claimed as registered forecasts.</p><a class="audit-link" href="forecasts.json">Inspect the forecast ledger ↗</a></article></div></section>
 <section id="analysis"><div class="bar"><h2>Which numbers appear most?</h2><div class="control"><label>Pool <select id="frequency-pool"><option value="main">Main numbers</option>{'<option value="special">Viking number</option>' if v else ''}</select></label><label>History <select id="frequency-period"><option value="all">All available draws</option><option value="100">Latest 100</option><option value="50">Latest 50</option></select></label></div></div><div id="heatmap" class="heatmap" aria-label="Number appearance counts"></div><p id="number-detail" aria-live="polite">Select a number to inspect its count.</p><p class="tiny" id="frequency-note"></p></section>
 <section id="numerology-study"><div class="bar"><h2>Date numbers and winning sum roots</h2><label>Winning sum <select id="root-pool"><option value="main">Main numbers only ({c['k']})</option><option value="total">{total_label}</option></select></label></div><p>A digital root reduces a positive sum to 1–9. Example: 48 → 4 + 8 = 12 → 1 + 2 = 3. The date root uses every digit of YYYY-MM-DD. Main, extra and combined views belong to the same draw and are not independent evidence.</p><div class="two-col"><div class="card"><h3>Observed / expected counts</h3><p class="tiny">Mint: observed · Purple: exact fair-draw expectation. Root probabilities are calculated from all valid combinations, rather than assumed equal.</p><div id="root-bars" class="study-bars"></div><details><summary>Table of counts</summary><table class="modeltable"><thead><tr><th>Root</th><th>Observed</th><th>Expected</th></tr></thead><tbody id="root-table-body"></tbody></table></details></div><div class="card"><h3>Does the date root match?</h3><p>Main sum root equals date root: <strong>{a['dateMainMatches']} of {len(rows)}</strong>. Fair-draw expectation: <strong>{a['expectedDateMain']:.2f}</strong>.</p><p>Combined sum root equals date root: <strong>{a['dateTotalMatches']} of {len(rows)}</strong>. Fair-draw expectation: <strong>{a['expectedDateTotal']:.2f}</strong>.</p><p>The most common main sum root is <strong>{max(a['roots'],key=lambda x:x['main'])['root']}</strong> ({max(x['main'] for x in a['roots'])} draws). Selecting the largest count after looking at many patterns can produce apparent relationships by chance. These counts do not establish a future advantage.</p><details><summary>{extra_label.title()} roots</summary><p>{' · '.join(str(x['root'])+': '+str(x['extra']) for x in a['roots'])}</p></details></div></div></section>
 <section id="evaluation"><h2>Check the model against chance</h2><div class="two-col"><div class="card"><h3>Retrospective chronological holdout</h3><p>The first {ev['train']} draws train the model; the last {ev['count']} ({day(ev['from'])}–{day(ev['to'])}) evaluate fixed learned coefficients. Rolling features use only results known before each prediction. The model is then refitted on available history for new selections.</p><table class="modeltable"><thead><tr><th>Brier score · lower is better</th><th>Model</th><th>Uniform</th></tr></thead><tbody><tr><td>Main inclusion probabilities</td><td>{ev['mainBrier']:.8f}</td><td>{ev['mainBaseline']:.8f}</td></tr>{f'<tr><td>Viking probabilities</td><td>{ev["specialBrier"]:.8f}</td><td>{ev["specialBaseline"]:.8f}</td></tr>' if v else ''}</tbody></table><p class="tiny">Brier score averages squared probability errors across numbers. It is not a jackpot hit rate. This is an exploratory retrospective check with no significance claim or independently validated advantage; the forward ledger below is the ongoing test.</p></div><div class="card"><h3>Exact jackpot probability</h3><div class="metric">1 in {fmt(total)}</div><p>{'C(48,6) × 5' if v else 'C(34,7)'} equally likely valid combinations.</p><label class="calc-line">Distinct lines<input id="row-count" type="number" min="1" max="{total}" step="1" value="1"></label><p id="calculated-odds"></p><p class="tiny">These are exact jackpot-match odds for distinct valid combinations in one fair draw. Duplicate lines do not add combinations. Smaller prizes are not included in this calculator.</p></div></div></section>
 <section id="forward-record"><h2>Registered selections: result review</h2><p>We compare each method on the same future draws and retain misses as well as hits. A single successful line cannot establish a reliable method.</p><div id="review-body"></div></section>
 <section id="same-calendar-date"><div class="bar"><h2>The same calendar date in earlier years</h2><label>Target date <input type="date" id="same-date"></label></div><p>Exact day and month only. Years with no draw on that date are omitted.</p><div class="table-scroll"><table class="archive-table"><thead><tr><th>Date</th><th>Main numbers</th><th>{extra_label.title()}</th></tr></thead><tbody id="same-date-body"></tbody></table></div></section>
 <section id="repeats"><h2>Exact historical repeats</h2><div class="card"><p><strong>{len(a['repeatedMain'])}</strong> repeated main-number sets{' · <strong>'+str(len(a['repeatedFull']))+'</strong> repeated complete main + Viking combinations' if v else ''} in this archive. A past appearance does not make a set less likely next time.</p>{''.join('<p>'+E(x['numbers'])+' — '+', '.join(day(s) for s in x['dates'])+'</p>' for x in a['repeatedMain']) or '<p class="tiny">No exact main-number set repeats in this available history.</p>'}</div></section>
 <section id="archive"><div class="bar"><h2>Official results archive</h2><label>Year <select id="year"><option value="all">All years</option>{''.join(f'<option>{y}</option>' for y in years)}</select></label></div><div class="table-scroll"><table class="archive-table"><thead><tr><th>Draw date</th><th>Main numbers</th><th>{extra_label.title()}</th></tr></thead><tbody id="archive-body"></tbody></table></div><div class="loadmore"><button type="button" id="more">Load more results</button></div><p class="coverage-note">{coverage} {len(rows)} weekly draws verified without gaps from {day(rows[0]['date'])} through {day(latest['date'])}.</p><div class="source-links"><a class="audit-link" href="results.html">Open the complete readable archive ↗</a><button type="button" id="export">Download official draw numbers (CSV)</button></div></section>
 <section class="sources" id="sources"><div><h2>Sources and rules</h2><p>{rule}</p><ul><li><a href="{E(c['rulesUrl'])}" rel="noopener">Norsk Tipping: official {name} rules</a></li><li><a href="{E(h['source'])}?fromDate={latest['date']}&amp;toDate={(dt.date.fromisoformat(latest['date'])+dt.timedelta(days=1)).isoformat()}">Norsk Tipping: latest official result data</a></li><li><a href="history.json">Verified historical snapshot (JSON)</a></li><li><a href="analysis.json">Analysis snapshot (JSON)</a></li></ul><p>Results are checked hourly. Only finalised results are accepted. Conflicting winning numbers, gaps or invalid pools stop the update so the last verified snapshot remains available. Check Norsk Tipping before relying on a prize claim.</p></div><div><h2>Questions</h2><details><summary>What is special about AI selection 2?</summary><p>It uses the same learned probability weights as AI 1, with a different deterministic sample. Frequent numbers are a little more likely to be selected when the fitted weights favour them. The output remains a guess; two hits do not prove the method works.</p></details><details><summary>Why separate the two games?</summary><p>The pools, schedules and jackpot odds differ. Lotto’s bonus is drawn, while Vikinglotto’s Viking number is chosen. Historical data and model results stay separate.</p></details><details><summary>Can numerology predict a lottery draw?</summary><p>This lab treats numerology as an exploratory hypothesis. A fair lottery draw is independent of dates, birthdays and earlier results. The lab reports counts and keeps a forward record so any claim can be checked.</p></details></div></section>
 <dialog id="line-editor" aria-labelledby="editor-title"><h2 id="editor-title">Choose your line</h2><p id="editor-count"></p><h3>Main numbers</h3><div class="editor-picks" id="pick-main"></div><h3 {'hidden' if not v else ''}>Viking number</h3><div class="editor-picks" id="pick-special" {'hidden' if not v else ''}></div><div class="dialog-actions"><button type="button" id="editor-close">Cancel</button><button type="button" id="editor-random">Random line</button><button type="button" id="editor-save" class="primary" disabled>Save line</button></div></dialog><div id="toast" role="status" hidden></div><script src="/LotteryLab/engine.js?v=1"></script><script src="/LotteryLab/numerology.js?v=1"></script><script src="/LotteryLab/app.js?v=1"></script>'''
 write(d/'index.html',top+foot())
 archive=head(f'{name} winning numbers archive {years[-1]}–{years[0]}',f'All {len(rows)} verified {name} draws from {rows[0]["date"]} through {latest["date"]}, with main numbers and {extra_label}.',folder,'results.html')
 archive+=f'<section class="hero"><div><span class="eyebrow">Official draw archive</span><h1>{name}<br><em>Winning numbers.</em></h1><p>{coverage}</p><a class="button-link" href="./">Return to the number lab →</a></div></section><p class="coverage-note">Source: Norsk Tipping official results API · {len(rows)} verified weekly draws · fetched {E(h["fetchedAt"])}.</p><nav class="year-links" aria-label="Archive year">'+''.join(f'<a href="#year-{y}">{y}</a>' for y in years)+'</nav>'
 for y in years:archive+=f'<section id="year-{y}"><h2>{y} results</h2>'+table([r for r in reversed(rows) if r['date'].startswith(y)],c)+'</section>'
 archive+='<p><a class="audit-link" href="history.json">Download verified source snapshot (JSON)</a></p>'
 write(d/'results.html',archive+foot());print(folder,'rendered',len(rows),'draws')
if __name__=='__main__':
 for folder in ['Lotto','Vikinglotto']:build(folder)
